/// <summary>
///     The <c>AVABPJobsUpdateStatusGLB</c> class is the execution class for <c>BP-Jobs</c>
/// </summary>
class AVABPJobsUpdateStatusGLB
{
    QueryRun                    queryRun;
    boolean                     lJobMode;
    KCS_KBVBuildingProjectID    kcs_KBVBuildingProjectID;
    container                   processingInterval;



}

Method.Source:
/// <summary>
/// N.Freidenberger 12.09.2025
/// </summary>
/// <param name = "_processingInterval">_processingInterval</param>
/// <returns>container</returns>
public container parmProcessingInterval(container       _processingInterval = processingInterval)
{
    processinginterval = _processingInterval;
    return processinginterval;
}

/// <summary>
///     AVA <c>init</c> method.
/// </summary>
public void init()
{
    lJobMode = false;
}

/// <summary>
///     AVA <c>initQuery</c> method.
/// </summary>
public void initQuery()
{
    Query                   query;
    QueryBuildDataSource    queryBuildDataSource;
    QueryBuildRange         qbr;
    str                     fromBVNum, toBVNum,zeroRecord;

    query = new Query();
    queryBuildDataSource = query.addDataSource(tablenum(KCS_KBVBuildingProjectTable));
    queryBuildDataSource.addRange(fieldnum(KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectID));

    queryRun = new QueryRun(query);


    qbr = AVABPJobsExecution::setKBVBuildingProjectIdRange( queryRun.query(),
                                                        tablenum(KCS_KBVBuildingProjectTable),
                                                        fieldnum(KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectID),
                                                        kcs_KBVBuildingProjectID);
    queryBuildDataSource.addRange(fieldNum(KCS_KBVBuildingProjectTable,KCS_KBVStatus)).value(strFmt('%1,%2,%3,%4',SysQuery::valueNot(KCS_KBVStatus::Locked),
        SysQuery::valueNot(KCS_KBVStatus::Won),SysQuery::valueNot(KCS_KBVStatus::Lost),SysQuery::valueNot(KCS_KBVStatus::Declined)));

    if (conLen(processinginterval) > 0)
    {
        fromBVNum = conPeek(processinginterval,1);
        toBVNum   = conPeek(processinginterval,2);
        zeroRecord = conPeek(processinginterval,3);

        if (toBVNum != zeroRecord)
        {
            qbr.value(strFmt('%1..%2', fromBVNum, toBVNum));
        }
        else
        {
            qbr.value(strFmt('%1..', fromBVNum));
        }
    }
}

/// <summary>
///     AVA <c>parmKCS_KBVBuildingProjectID</c> method.
/// </summary>
/// <param name="_parmValue">
///     <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <returns>
///     <c>KCS_KBVBuildingProjectID</c> as return value
/// </returns>
public KCS_KBVBuildingProjectID parmKCS_KBVBuildingProjectID(KCS_KBVBuildingProjectID _parmValue = kcs_KBVBuildingProjectID)
{
    kcs_KBVBuildingProjectID = _parmValue;

    return kcs_KBVBuildingProjectID;
}

/// <summary>
///     AVA <c>parmlJobMode</c> method.
/// </summary>
/// <param name="_parmValue">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean parmlJobMode(boolean _parmValue = lJobMode)
{
    lJobMode = _parmValue;

    return lJobMode;
}

/// <summary>
///     AVA <c>run</c> method.
/// </summary>
public void run()
{
    KCS_KBVBuildingProjectTable kcs_KBVBuildingProjectTable;
    NDX_KBVJobProt              nDX_KBVJobProt;

    #OCCRetryCount

    nDX_KBVJobProt.createProt(NDX_KBVJob::KBV_PeriodicUpdate, lJobMode);

    try
    {
        while (queryRun.next())
        {
            if (queryRun.changed(tablenum(KCS_KBVBuildingProjectTable)))
            {
                ttsBegin;
                kcs_KBVBuildingProjectTable = queryRun.get(tablenum(KCS_KBVBuildingProjectTable));
                KCS_KBVBuildingProjectTable::updateBPStatus(kcs_KBVBuildingProjectTable, !lJobMode);
                ttsCommit;
            }
        }
    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                if (conLen(this.parmProcessingInterval()) > 0)
                {
                    error(strFmt("@NDX:NXABPUpdateConflictBatch",kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID));
                }
                else
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw;
        }
    }

    nDX_KBVJobProt.createProt(NDX_KBVJob::KBV_PeriodicUpdate, lJobMode, false);

}

/// <summary>
///     AVA <c>statusPerProductGroup</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectID">
///     <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_kcs_DirProductGroupID">
///     <c>KCS_DirProductGroupID</c> as type
/// </param>
/// <returns>
///     <c>int</c> as return value
/// </returns>
static int statusPerProductGroup(KCS_KBVBuildingProjectID _kcs_KBVBuildingProjectID, KCS_DirProductGroupID _kcs_DirProductGroupID)
{
    SalesQuotationTable salesQuotationTable;
    int                 numOfQuotations, numOfLostQuot;

    while select QuotationStatus, KCS_KBVBuildingProjectID, KCS_KBVProductGroupID
    from    salesQuotationTable
    where   salesQuotationTable.KCS_KBVBuildingProjectID    == _KCS_KBVBuildingProjectID
        &&  salesQuotationTable.KCS_KBVProductGroupID       == _kcs_DirProductGroupID
    {
        numOfQuotations++;
        if (salesQuotationTable.QuotationStatus == SalesQuotationStatus::Confirmed)
        {
            return 1;
        }

        if (salesQuotationTable.QuotationStatus == SalesQuotationStatus::Lost)
        {
            numOfLostQuot++;
        }
    }

    if (numOfLostQuot == numOfQuotations)
    {
        return 2;
    }

    return 0;
}
